import React, { useState, useEffect } from "react"
import styled from "styled-components"
import _ from "lodash"

import { Link } from "gatsby"
import { FaArrowRight } from "react-icons/fa"

import Title from "components/Title"
import Divider from "components/Divider"
import TagList from "components/TagList"

const PostListWrapper = styled.div`
  display: grid;
  gap: 32px;
  
  @media (max-width: 768px) {
    padding: 0 16px;
    gap: 24px;
  }
`

const PostWrapper = styled.article`
  position: relative;
  background: ${props => props.theme?.name === 'dark' ? '#1a1a1a' : '#ffffff'};
  border-radius: 20px;
  border: 1px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  padding: 32px;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  overflow: hidden;
  
  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    transform: translateX(-100%);
    transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px ${props => props.theme?.name === 'dark' ? 'rgba(59, 130, 246, 0.2)' : 'rgba(37, 99, 235, 0.1)'};
    border-color: #2563eb;
  }

  &:hover::before {
    transform: translateX(0);
  }

  @media (max-width: 768px) {
    padding: 24px;
  }
`

const PostLink = styled(Link)`
  text-decoration: none;
  color: inherit;
  display: block;
`

const PostHeader = styled.div`
  margin-bottom: 24px;
`

const PostTitle = styled.h2`
  font-size: 24px;
  font-weight: 700;
  color: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#0a0a0a'};
  margin-bottom: 0;
  line-height: 1.3;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  
  &:hover {
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  @media (max-width: 768px) {
    font-size: 20px;
  }
`

const Date = styled.time`
  display: inline-flex;
  align-items: center;
  font-size: 13px;
  color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
  background: ${props => props.theme?.name === 'dark' ? 'rgba(59, 130, 246, 0.1)' : 'rgba(37, 99, 235, 0.05)'};
  padding: 6px 12px;
  border-radius: 12px;
  border: 1px solid ${props => props.theme?.name === 'dark' ? 'rgba(59, 130, 246, 0.2)' : 'rgba(37, 99, 235, 0.1)'};
  font-weight: 500;
  letter-spacing: 0.3px;
  margin-bottom: 16px;
  width: fit-content;
  
  &::before {
    content: '⏰';
    margin-right: 6px;
    font-size: 11px;
  }
`

const PostContent = styled.div`
  margin-bottom: 24px;
`

const Excerpt = styled.p`
  line-height: 1.7;
  font-size: 16px;
  color: ${props => props.theme?.name === 'dark' ? '#d1d5db' : '#374151'};
  margin-bottom: 20px;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  
  @media (max-width: 768px) {
    font-size: 15px;
    -webkit-line-clamp: 2;
  }
`

const PostFooter = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  
  @media (max-width: 768px) {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
`

const ReadMoreButton = styled.div`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  border-radius: 50%;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  cursor: pointer;
  
  &:hover {
    transform: translateX(4px) scale(1.05);
    box-shadow: 0 8px 24px rgba(37, 99, 235, 0.4);
  }
  
  & svg {
    color: #ffffff;
    font-size: 16px;
    transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }
  
  &:hover svg {
    transform: translateX(2px);
  }

  @media (max-width: 768px) {
    width: 40px;
    height: 40px;
    
    & svg {
      font-size: 14px;
    }
  }
`

const LoadingIndicator = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  font-size: 16px;
  color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
  
  &::before {
    content: '';
    width: 20px;
    height: 20px;
    border: 2px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
    border-top: 2px solid #2563eb;
    border-radius: 50%;
    animation: spin 1s linear infinite;
    margin-right: 12px;
  }
  
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`

const checkIsScrollAtBottom = () => {
  return (
    document.documentElement.scrollHeight -
      document.documentElement.scrollTop <=
    document.documentElement.clientHeight + 100
  )
}

const PostList = ({ postList }) => {
  const [postCount, setPostCount] = useState(10)
  const [isLoading, setIsLoading] = useState(false)

  const handleMoreLoad = _.throttle(() => {
    if (checkIsScrollAtBottom() && postCount < postList.length) {
      setIsLoading(true)
      setTimeout(() => {
        setPostCount(postCount + 10)
        setIsLoading(false)
      }, 300)
    }
  }, 250)

  useEffect(() => {
    window.addEventListener("scroll", handleMoreLoad)

    return () => {
      window.removeEventListener("scroll", handleMoreLoad)
    }
  }, [postCount, postList])

  useEffect(() => {
    setPostCount(10)
  }, [postList])

  return (
    <>
      <PostListWrapper>
        {postList.slice(0, postCount).map((post, i) => {
          const { title, date, tags } = post.frontmatter
          const { excerpt } = post
          const { slug } = post.fields

          return (
            <PostWrapper key={JSON.stringify({ slug, date })}>
              <PostLink to={slug}>
                <PostHeader>
                  <Date dateTime={date}>{date}</Date>
                  <PostTitle>{title}</PostTitle>
                </PostHeader>
                
                <PostContent>
                  <Excerpt>{excerpt}</Excerpt>
                </PostContent>
                
                <PostFooter>
                  <TagList tagList={tags} />
                  <ReadMoreButton>
                    <FaArrowRight />
                  </ReadMoreButton>
                </PostFooter>
              </PostLink>
            </PostWrapper>
          )
        })}
      </PostListWrapper>
      
      {isLoading && (
        <LoadingIndicator>
          Loading more posts...
        </LoadingIndicator>
      )}
    </>
  )
}

export default PostList
